camel_example:
aliyun eas POST /api/v2/services --region cn-hangzhou --Develop true --WorkspaceId 123456 --Labels '{"key":"{"key":"value"}"}' --header "Content-Type=application/json" --body '"Image deployment service:
{
  "name": "foo",
  "metadata": {
    "instance": 2,
    "memory": 7000,
    "cpu": 4
    },
  "containers": [
    {
      "image": "****",
      "script": "**** --listen=0.0.0.0 --server_port=8000 --headless",
      "port": 8000
    }
  ],
  "storage": [
    {
      "oss": {
        "path": "oss://examplebuket/data111/",
        "readOnly": false
      },
      "properties": {
        "resource_type": "model"
      },
      "mount_path": "/data"
    }
  ]
}
